def render_icon(svg_string: str, size: int = 24, color: str = "#d4a85a",
                device_pixel_ratio: float = 1.0) -> QPixmap:
    svg = svg_string.replace("currentColor", color)
    renderer = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    actual_size = max(1, int(size * device_pixel_ratio))
    pixmap = QPixmap(actual_size, actual_size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    renderer.render(painter)
    painter.end()
    pixmap.setDevicePixelRatio(device_pixel_ratio)
    return pixmap


def make_icon(svg_string: str, size: int = 24, color: str = "#d4a85a",
              device_pixel_ratio: float = 1.0) -> QIcon:
    return QIcon(render_icon(svg_string, size, color, device_pixel_ratio))


def get_dpr() -> float:
    app = QApplication.instance()
    return app.devicePixelRatio() if app else 1.0
